import 'dart:convert'; import 'dart:io'; void main() { final data = jsonDecode(File('.dart_tool/package_config.json').readAsStringSync()); final pkg = (data['packages'] as List).cast<Map<String,dynamic>>().firstWhere((p) => p['name'] == 'the_ranger_mobile'); final root = Uri.parse(pkg['rootUri']); final pkgUri = Uri.parse(pkg['packageUri']); final base = Uri.file(Directory.current.path + Platform.pathSeparator); final fullRoot = base.resolveUri(root); final target = fullRoot.resolveUri(pkgUri).resolve('views/auth/pemilik_marketplace/mitra_marketplace_dashboard_view.dart'); print('root: ../'); print('packageUri: '); print('fullRoot: '); print('target: '); print(File.fromUri(target).existsSync()); }
